"""Prepare reviewable, field-scoped repairs. This script does not edit the bank."""
from pathlib import Path
import json,copy
OUT=Path(__file__).resolve().parent
before=json.loads((OUT/'questions.before.json').read_text(encoding='utf-8'))
original={q['id']:q for q in before}
work=copy.deepcopy(original)
issues={}
def mark(i,issue,refs): issues[i]={'issue':issue,'references':refs}
def correct(i,en,th):work[i]['explanation_detail']['correct']={'en':en,'th':th}
def wrong(i,l,en,th):
 r=next(r for r in work[i]['explanation_detail']['incorrect'] if r['letter']==l);r.update(text_en=en,text_th=th)
def tip(i,en,th):work[i]['explanation_detail']['exam_tip']={'en':en,'th':th}
def example(i,en,th):work[i]['explanation_detail']['example']={'en':en,'th':th}
def flats(i):
 q=work[i];d=q['explanation_detail'];q['explanation']=d['correct']['en']+'\n'+'\n'.join(r['letter']+': '+r['text_en'] for r in d['incorrect']);q['explanation_th']=d['correct']['th']+'\n'+'\n'.join(r['letter']+': '+r['text_th'] for r in d['incorrect'])

mark(588,'Structured explanation describes Accounting instead of the password/PIN factor question.',['R01','R02','L01'])
correct(588,'The password and the PIN entered on this login screen are both knowledge factors: something you know. Two secrets of the same factor type do not meet the requirement for multiple distinct authentication factors.','รหัสผ่านและ PIN ที่กรอกบนหน้าจอล็อกอินนี้เป็นปัจจัยประเภทสิ่งที่คุณรู้ (Knowledge factor) ทั้งคู่ การใช้ความลับสองอย่างในปัจจัยประเภทเดียวกันจึงไม่ตรงตามข้อกำหนดที่ต้องใช้ปัจจัยต่างประเภทกันของ MFA')
wrong(588,'A','PIN strength matters to security, but its length does not change its factor category. Even a longer PIN combined only with a password would still use knowledge factors.','ความแข็งแรงของ PIN มีผลต่อความปลอดภัย แต่ความยาวไม่ได้เปลี่ยนประเภทปัจจัย แม้ใช้ PIN ที่ยาวขึ้นร่วมกับรหัสผ่านเพียงอย่างเดียวก็ยังเป็นปัจจัยประเภทสิ่งที่คุณรู้')
wrong(588,'C','MFA requires at least two distinct factor types, not necessarily three. The problem here is that both supplied secrets have the same type.','MFA ต้องใช้ปัจจัยต่างประเภทกันอย่างน้อยสองประเภท ไม่จำเป็นต้องครบสามประเภท ปัญหาในโจทย์คือความลับทั้งสองอย่างเป็นปัจจัยประเภทเดียวกัน')
wrong(588,'D','A PIN can be entered in software or used to activate an authenticator. It is not restricted to hardware-token entry; a PIN plus a password alone does not demonstrate possession of such a token.','PIN สามารถกรอกผ่านซอฟต์แวร์หรือใช้ปลดล็อกสิ่งที่ใช้พิสูจน์ตัวตนได้ ไม่ได้จำกัดว่าต้องกรอกบนฮาร์ดแวร์โทเคน และ PIN ร่วมกับรหัสผ่านเพียงอย่างเดียวไม่ได้แสดงว่าผู้ใช้ครอบครองโทเคนดังกล่าว')

mark(589,'Structured explanation describes non-repudiation instead of privacy roles.',['R01','R03','L02'])
correct(589,'The cloud provider is the Data Processor in the stated arrangement because it stores and processes personal data on the retailer’s instructions. The retailer determines the processing purpose; cloud hosting alone does not make the provider the controller.','ผู้ให้บริการคลาวด์เป็นผู้ประมวลผลข้อมูลส่วนบุคคล (Data Processor) ในความสัมพันธ์ตามโจทย์ เพราะจัดเก็บและประมวลผลข้อมูลตามคำสั่งของบริษัทค้าปลีก บริษัทค้าปลีกเป็นผู้กำหนดวัตถุประสงค์ การให้บริการโฮสต์บนคลาวด์เพียงอย่างเดียวไม่ได้ทำให้ผู้ให้บริการเป็นผู้ควบคุมข้อมูล')
wrong(589,'A','The Data Subjects are the individuals whose shipping and payment information is processed, rather than the hosting provider.','Data Subject คือบุคคลที่ข้อมูลการจัดส่งและการชำระเงินของตนถูกประมวลผล ไม่ใช่ผู้ให้บริการโฮสต์')
wrong(589,'B','A Data Controller determines the purposes and means of processing. Here the retailer directs the processing, while the provider acts on its instructions.','Data Controller เป็นผู้กำหนดวัตถุประสงค์และวิธีการประมวลผล ในโจทย์บริษัทค้าปลีกเป็นผู้กำหนดการประมวลผล ส่วนผู้ให้บริการปฏิบัติตามคำสั่ง')
wrong(589,'D','A Data Protection Authority supervises compliance with data-protection law. The provider is supplying a processing service, not acting as that regulator.','Data Protection Authority เป็นหน่วยงานกำกับการปฏิบัติตามกฎหมายคุ้มครองข้อมูล ผู้ให้บริการในโจทย์ให้บริการประมวลผล ไม่ได้ทำหน้าที่เป็นหน่วยงานกำกับดังกล่าว')

mark(590,'Structured explanation describes threats rather than inventory; flat EN also confuses a sanitization schedule with procedures.',['R01','R04','L02'])
correct(590,'A data inventory records the categories of information held, their storage locations and their responsible owners. Those are the facts needed for the stated data-mapping exercise.','Data inventory บันทึกประเภทข้อมูลที่องค์กรมี สถานที่จัดเก็บ และเจ้าของหรือผู้รับผิดชอบข้อมูล ซึ่งตรงกับข้อมูลที่ต้องใช้ในการจัดทำแผนผังข้อมูลตามโจทย์')
wrong(590,'A','A retention policy defines how long records are kept and when disposal is appropriate; it does not itself catalog the data, locations and owners.','นโยบายการเก็บรักษาข้อมูลกำหนดว่าต้องเก็บข้อมูลนานเท่าใดและควรทำลายเมื่อใด ไม่ได้ทำหน้าที่จัดทำบัญชีประเภทข้อมูล สถานที่จัดเก็บ และเจ้าของข้อมูลโดยตรง')
wrong(590,'C','A sanitization schedule sets when data or media is to be sanitized. It does not provide the requested catalog of existing datasets and their owners.','ตารางการทำลายข้อมูลอย่างปลอดภัยกำหนดเวลาที่ต้องล้างข้อมูลหรือจัดการสื่อบันทึก ไม่ได้ให้บัญชีชุดข้อมูลที่มีอยู่และเจ้าของข้อมูลตามที่ต้องการ')
wrong(590,'D','A masking standard specifies how sensitive fields are obscured for an authorized use. It does not identify every dataset, storage location and owner.','มาตรฐานการพรางข้อมูลกำหนดวิธีปิดบังข้อมูลอ่อนไหวเพื่อการใช้งานที่ได้รับอนุญาต ไม่ได้ระบุชุดข้อมูลทั้งหมด สถานที่จัดเก็บ และเจ้าของข้อมูล')
flats(590)

mark(591,'Structured explanation describes a generic risk formula and unrelated exclusions rather than the displayed asset/threat/vulnerability/impact choices.',['R01','R05','L03'])
correct(591,'The unpatched code-execution flaw is a Vulnerability: a weakness that a threat could exploit. The question asks about the flaw itself, not the asset containing it or the resulting harm.','ข้อบกพร่องที่ยังไม่ได้แพตช์และเปิดทางให้รันโค้ดได้เป็นช่องโหว่ (Vulnerability) คือจุดอ่อนที่ภัยคุกคามอาจใช้ประโยชน์ได้ โจทย์ถามถึงข้อบกพร่อง ไม่ใช่ทรัพย์สินที่มีข้อบกพร่องหรือความเสียหายที่ตามมา')
wrong(591,'A','The web server and customer database are assets of value. The software flaw is a weakness in an asset, not the asset itself.','เว็บเซิร์ฟเวอร์และฐานข้อมูลลูกค้าเป็นทรัพย์สินที่มีคุณค่า ส่วนข้อบกพร่องของซอฟต์แวร์เป็นจุดอ่อนในทรัพย์สิน ไม่ใช่ตัวทรัพย์สินเอง')
wrong(591,'B','The malicious actors and the potential attack are sources or events of threat. The exploitable software flaw is the vulnerability they could use.','ผู้ไม่หวังดีและการโจมตีที่อาจเกิดขึ้นเป็นแหล่งหรือเหตุการณ์ของภัยคุกคาม ส่วนข้อบกพร่องของซอฟต์แวร์ที่ใช้โจมตีได้เป็นช่องโหว่')
wrong(591,'D','Impact is the harm resulting from an incident, such as disclosure or alteration of customer records. The flaw is a condition that can enable that harm.','Impact คือความเสียหายที่เกิดจากเหตุการณ์ เช่น ข้อมูลลูกค้าถูกเปิดเผยหรือแก้ไข ส่วนข้อบกพร่องเป็นสภาวะที่อาจเปิดทางให้เกิดความเสียหายนั้น')

mark(596,'C/D distractor rationales are attached to different displayed choices.',['R06','L04'])
wrong(596,'C','Software versions and scan-script output may support technical investigation, but this inventory alone does not explain prioritized business impacts or investment needs to the board.','หมายเลขเวอร์ชันและผลลัพธ์สคริปต์สแกนอาจใช้สนับสนุนการตรวจสอบทางเทคนิค แต่รายการเหล่านี้เพียงอย่างเดียวไม่ได้อธิบายผลกระทบทางธุรกิจที่จัดลำดับแล้วหรือความต้องการลงทุนต่อคณะกรรมการ')
wrong(596,'D','Budget approval cannot guarantee that every residual cyber risk becomes zero. Reporting should communicate remaining risk and the expected benefits and limits of proposed controls.','การอนุมัติงบประมาณไม่สามารถรับประกันว่าความเสี่ยงทางไซเบอร์ที่เหลืออยู่ทุกอย่างจะเป็นศูนย์ รายงานควรสื่อสารความเสี่ยงที่เหลือและประโยชน์รวมถึงข้อจำกัดที่คาดหวังจากมาตรการที่เสนอ')

mark(597,'C refers to software development absent from the option; D incorrectly receives the zero-risk rationale.',['R06','L04'])
wrong(597,'C','Governance directs and oversees risk management; it cannot guarantee that a breach or outage will never occur.','Governance กำหนดทิศทางและกำกับการบริหารความเสี่ยง แต่ไม่สามารถรับประกันว่าจะไม่มีการละเมิดข้อมูลหรือระบบหยุดทำงานเลย')
wrong(597,'D','Configuring firewalls and writing detection rules implement technical controls. These activities support governance decisions but are not the enterprise-level direction and oversight asked about.','การตั้งค่าไฟร์วอลล์และเขียนกฎตรวจจับเป็นการนำมาตรการทางเทคนิคไปใช้ งานเหล่านี้สนับสนุนการตัดสินใจด้าน Governance แต่ไม่ใช่การกำหนดทิศทางและกำกับดูแลระดับองค์กรที่โจทย์ถาม')

mark(599,'B guideline and D policy rationales are swapped.',['L04'])
wrong(599,'B','A guideline gives recommended practice rather than the mandatory technical requirements explicitly specified in this document.','Guideline เป็นคำแนะนำในการปฏิบัติ ไม่ใช่ข้อกำหนดทางเทคนิคภาคบังคับที่ระบุอย่างชัดเจนในเอกสารนี้')
wrong(599,'D','A policy states management direction and expectations. The mandatory lock interval and encryption specification are the detailed standard implementing that direction.','Policy ระบุทิศทางและความคาดหวังของผู้บริหาร ส่วนระยะเวลาล็อกหน้าจอและข้อกำหนดการเข้ารหัสภาคบังคับเป็นรายละเอียดของ Standard ที่ใช้ดำเนินการตามทิศทางนั้น')

mark(601,'Distractor rationales misstate the categories actually assigned in B/C/D; acknowledge the three-category model rather than imposing it on every taxonomy.',['R01','L05'])
wrong(601,'B','Under the technical/administrative/physical classification used here, the packet-inspecting firewall is technical, and background checks/training are administrative personnel measures. B instead calls them operational and technical.','ภายใต้การแบ่งเป็น Technical/Administrative/Physical ที่ใช้ในข้อนี้ ไฟร์วอลล์ตรวจแพ็กเก็ตเป็นมาตรการทางเทคนิค ส่วนการตรวจประวัติและอบรมเป็นมาตรการด้านบุคลากรทางการบริหาร ข้อ B กลับจัดเป็น Operational และ Technical ตามลำดับ')
wrong(601,'C','C calls the firewall physical and the facility barriers managerial/administrative. The firewall’s packet inspection is technical, while the fences and turnstiles control physical entry.','ข้อ C จัดไฟร์วอลล์เป็น Physical และสิ่งกีดขวางอาคารเป็น Managerial/Administrative แต่การตรวจแพ็กเก็ตเป็นกลไกทางเทคนิค ส่วนรั้วและประตูกั้นควบคุมการเข้าถึงทางกายภาพ')
wrong(601,'D','D correctly identifies the firewall as technical, but calls background checks/training physical and facility barriers operational. Those measures are administrative and physical respectively in the classification used here.','ข้อ D จัดไฟร์วอลล์เป็น Technical ถูกต้อง แต่จัดการตรวจประวัติและอบรมเป็น Physical และสิ่งกีดขวางอาคารเป็น Operational ซึ่งในกรอบการแบ่งประเภทที่ใช้ในข้อนี้ควรเป็น Administrative และ Physical ตามลำดับ')

mark(603,'B/C detective/preventive rationales are swapped; Thai stem omitted the supplied write-once backup property.',['L05','R10'])
wrong(603,'B','Detective controls identify or alert on events. Restoring the affected systems is corrective recovery rather than the act of detecting the ransomware.','Detective control ใช้ระบุหรือตรวจพบเหตุการณ์และแจ้งเตือน ส่วนการกู้คืนระบบที่ได้รับผลกระทบเป็นการแก้ไขฟื้นฟู ไม่ใช่การตรวจจับ Ransomware')
wrong(603,'C','Preventive controls aim to stop an unwanted event before it occurs. Here the infection has already damaged systems and the stated action restores them.','Preventive control มุ่งป้องกันเหตุที่ไม่ต้องการก่อนเกิดเหตุ แต่ในโจทย์ระบบได้รับความเสียหายจากการติดเชื้อแล้ว และการกระทำที่ถามคือการกู้คืนระบบ')
work[603]['question_th']=work[603]['question_th'].replace('(Offline backup)','(Offline backup) แบบเขียนได้ครั้งเดียว (Write-once)')

mark(611,'D describes PCI DSS rather than NIST SP800-30; accreditation applies to certification bodies, and Thai example incorrectly calls surveillance annual renewal.',['R09','R05','R06','L06'])
correct(611,'ISO/IEC 27001 specifies requirements for an Information Security Management System (ISMS) against which an organization can obtain independent third-party certification. Accreditation concerns the competence of a certification body; it is not accreditation of the standard itself.','ISO/IEC 27001 กำหนดข้อกำหนดสำหรับระบบบริหารจัดการความมั่นคงปลอดภัยสารสนเทศ (ISMS) ที่องค์กรสามารถขอรับการตรวจรับรองจากหน่วยงานภายนอกได้ Accreditation เป็นการรับรองความสามารถของหน่วยงานตรวจรับรอง ไม่ใช่การรับรองตัวมาตรฐาน')
wrong(611,'B','NIST CSF 2.0 organizes cybersecurity outcomes and risk-management guidance; NIST does not offer an organizational ISMS certification through the CSF.','NIST CSF 2.0 จัดหมวดผลลัพธ์และแนวทางบริหารความเสี่ยงด้านความมั่นคงปลอดภัย โดย NIST ไม่ได้จัดให้มีการตรวจรับรอง ISMS ขององค์กรผ่าน CSF')
wrong(611,'D','NIST SP 800-30 Rev. 1 guides the conduct of risk assessments. It is not a set of certifiable ISMS requirements like ISO/IEC 27001.','NIST SP 800-30 Rev. 1 ให้แนวทางการประเมินความเสี่ยง ไม่ใช่ชุดข้อกำหนด ISMS สำหรับการตรวจรับรองแบบ ISO/IEC 27001')
example(611,'An organization may use its ISO/IEC 27001 certificate, including its scope and validity, as one input to a customer’s supplier assessment. Certification does not replace assessment of the customer’s specific risks.','องค์กรอาจใช้ใบรับรอง ISO/IEC 27001 พร้อมขอบเขตและระยะเวลาที่มีผล เป็นข้อมูลส่วนหนึ่งในการประเมินผู้ให้บริการของลูกค้า การมีใบรับรองไม่ได้ทดแทนการประเมินความเสี่ยงเฉพาะของลูกค้า')
work[611]['question']=work[611]['question'].replace('internationally accredited,','internationally recognized,')
work[611]['question_th']=work[611]['question_th'].replace('ที่ได้รับการรับรองในระดับสากล','ที่เป็นที่ยอมรับในระดับสากล')
flats(611)

mark(592,'Quantitative assessment is incorrectly defined as requiring precise monetary valuations.',['R05','L03'])
correct(592,'The descriptive High/Medium/Low ratings and expert judgment make this qualitative risk analysis. Quantitative analysis uses numerical values with meaningful units and relationships; financial loss estimates are one example, not its only form.','การให้ระดับเชิงพรรณนา High/Medium/Low โดยอาศัยดุลยพินิจของผู้เชี่ยวชาญเป็นการวิเคราะห์ความเสี่ยงเชิงคุณภาพ ส่วนการวิเคราะห์เชิงปริมาณใช้ค่าตัวเลขที่มีหน่วยและความสัมพันธ์ที่มีความหมาย การประมาณความสูญเสียทางการเงินเป็นเพียงตัวอย่างหนึ่ง ไม่ใช่รูปแบบเดียว')
wrong(592,'A','Quantitative analysis uses numerical estimates whose meaning and scale support comparison, such as loss amounts or occurrence frequencies. The supplied descriptive categories do not provide such measurements.','การวิเคราะห์เชิงปริมาณใช้ค่าประมาณตัวเลขที่มีความหมายและมาตราส่วนสำหรับเปรียบเทียบ เช่น มูลค่าความสูญเสียหรือความถี่การเกิดเหตุ ระดับเชิงพรรณนาในโจทย์ไม่ได้ให้ค่าการวัดลักษณะนั้น')

mark(595,'Thai acceptance rationale adds ignoring impacts; avoidance wording should refer to the declined activity, not all organizational risk.',['R05','L03'])
correct(595,'Declining to deploy this platform avoids the exposure associated with using it. This is avoidance of the specified activity, not a claim that all healthcare or privacy risks disappear.','การไม่นำแพลตฟอร์มนี้มาใช้เป็นการหลีกเลี่ยงความเสี่ยงที่เกิดจากการใช้งานแพลตฟอร์มนั้น เป็นการหลีกเลี่ยงกิจกรรมที่ระบุ ไม่ได้หมายความว่าความเสี่ยงด้านสุขภาพหรือความเป็นส่วนตัวทั้งหมดจะหายไป')
wrong(595,'B','Mitigation would use safeguards to reduce risk while continuing with the activity, rather than declining deployment.','Mitigation ใช้มาตรการลดความเสี่ยงโดยยังดำเนินกิจกรรมต่อ ต่างจากการตัดสินใจไม่นำระบบมาใช้')
wrong(595,'D','Acceptance would retain the identified risk through an informed decision by an authorized party. It does not mean ignoring possible impacts; the organization instead declines the activity here.','Acceptance คือการคงรับความเสี่ยงที่ระบุไว้โดยผู้มีอำนาจตัดสินใจอย่างมีข้อมูล ไม่ใช่การเพิกเฉยต่อผลกระทบที่อาจเกิดขึ้น แต่ในโจทย์องค์กรเลือกไม่ดำเนินกิจกรรมนั้น')

mark(600,'An ISO/IEC27001 requirements standard is conflated with a cybersecurity framework.',['R06','R09','L04'])
correct(600,'A cybersecurity framework such as NIST CSF provides a structure for assessing, prioritizing and communicating cybersecurity outcomes across a program. ISO/IEC 27001 is a related ISMS requirements standard, rather than another name for the CSF.','กรอบการทำงานด้านความมั่นคงปลอดภัย เช่น NIST CSF ช่วยจัดโครงสร้างการประเมิน จัดลำดับความสำคัญ และสื่อสารผลลัพธ์ด้านความมั่นคงปลอดภัยของโปรแกรม ส่วน ISO/IEC 27001 เป็นมาตรฐานข้อกำหนด ISMS ที่เกี่ยวข้อง ไม่ใช่อีกชื่อหนึ่งของ CSF')

mark(612,'Explanation treats organizational authority as inherent in job titles, including zero vendor authority.',['R06','L06'])
correct(612,'The designated business asset owner is the best choice among these options because the decision balances payroll business impact and security exposure. Authority to accept risk or approve downtime must be assigned by organizational governance; decisions beyond that authority require escalation.','เจ้าของทรัพย์สินทางธุรกิจที่ได้รับมอบหมายเหมาะสมที่สุดในบรรดาตัวเลือก เพราะต้องชั่งน้ำหนักผลกระทบต่องานเงินเดือนกับความเสี่ยงด้านความปลอดภัย อำนาจยอมรับความเสี่ยงหรืออนุมัติการหยุดระบบต้องได้รับการกำหนดโดยการกำกับดูแลองค์กร และต้องส่งต่อเมื่อเกินอำนาจนั้น')
wrong(612,'B','The analyst can provide vulnerability evidence and recommendations, but the scenario does not assign the analyst authority over payroll business-risk acceptance or downtime.','นักวิเคราะห์สามารถให้หลักฐานช่องโหว่และข้อเสนอแนะได้ แต่โจทย์ไม่ได้มอบอำนาจตัดสินใจยอมรับความเสี่ยงทางธุรกิจหรือหยุดระบบเงินเดือนให้แก่นักวิเคราะห์')
wrong(612,'D','The vendor engineer can advise on the flaw and remediation. Publishing an advisory does not confer authority to accept the customer’s business risk or approve its outage.','วิศวกรของผู้ขายสามารถให้คำแนะนำเรื่องช่องโหว่และการแก้ไขได้ การเผยแพร่คำแนะนำไม่ได้ทำให้มีอำนาจยอมรับความเสี่ยงทางธุรกิจหรืออนุมัติการหยุดระบบของลูกค้า')
tip(612,'Check the designated decision authority and business impact. A job title alone does not establish permission to accept risk.','ตรวจสอบผู้มีอำนาจตัดสินใจที่ได้รับมอบหมายและผลกระทบทางธุรกิจ ชื่อตำแหน่งเพียงอย่างเดียวไม่ได้ทำให้มีอำนาจยอมรับความเสี่ยง')

mark(613,'Cessation does not automatically erase risk-register history; outsourcing example overstates avoidance of all payment risk.',['R05','L03'])
correct(613,'Permanently retiring the vulnerable device and its diagnostic service stops the specified risk-bearing activity, illustrating Risk Avoidance. Record the disposition and any remaining transition risks rather than assuming that risk-register history disappears.','การเลิกใช้อุปกรณ์ที่มีช่องโหว่และยุติบริการตรวจวินิจฉัยนั้นอย่างถาวรเป็นการหยุดกิจกรรมที่ก่อความเสี่ยง จึงเป็น Risk Avoidance ควรบันทึกผลการจัดการและความเสี่ยงช่วงเปลี่ยนผ่านที่ยังเหลือ ไม่ใช่ถือว่าประวัติในทะเบียนความเสี่ยงหายไปเอง')
example(613,'The hospital retires the unsupported device and ends the associated service rather than continuing to operate it with additional controls. Other hospital risks still require management.','โรงพยาบาลเลิกใช้อุปกรณ์ที่หมดการสนับสนุนและยุติบริการที่เกี่ยวข้อง แทนการใช้งานต่อพร้อมเพิ่มมาตรการควบคุม ความเสี่ยงอื่นของโรงพยาบาลยังต้องได้รับการจัดการ')
tip(613,'Avoidance stops the specified activity. Mitigation reduces its risk while the activity continues; transfer and acceptance do not by themselves stop it.','Avoidance หยุดกิจกรรมที่ระบุ ส่วน Mitigation ลดความเสี่ยงขณะยังดำเนินกิจกรรมต่อ และ Transfer กับ Acceptance ไม่ได้หยุดกิจกรรมนั้นโดยตัวมันเอง')

mark(614,'Explanation asserts blanket international-methodology compliance solely from use of numeric scales.',['R05','L06'])
wrong(614,'C','NIST SP 800-30 recognizes semi-quantitative scales. Using numbers is not itself a violation; whether the method is appropriate depends on the defined scales, assumptions and assessment context.','NIST SP 800-30 ยอมรับการใช้มาตราส่วนกึ่งเชิงปริมาณ การใช้ตัวเลขไม่ได้เป็นการละเมิดโดยตัวมันเอง ส่วนวิธีการเหมาะสมหรือไม่ขึ้นกับนิยามมาตราส่วน สมมติฐาน และบริบทการประเมิน')

mark(616,'BIA is described as universally mandatory first rather than first for these unresolved recovery priorities.',['R10','L06'])
correct(616,'Because recovery priorities have not been established in this scenario, a BIA should identify critical functions, downtime impacts and dependencies before selecting recovery resources. This supports an evidence-based resolution of the departments’ competing requests.','ในสถานการณ์นี้ยังไม่ได้กำหนดลำดับความสำคัญในการกู้คืน จึงควรทำ BIA เพื่อระบุหน้าที่สำคัญ ผลกระทบจากการหยุดทำงาน และการพึ่งพาระหว่างระบบ ก่อนเลือกทรัพยากรกู้คืน เพื่อใช้หลักฐานตัดสินคำขอที่ขัดแย้งกันของแต่ละฝ่าย')
tip(616,'For this scenario, determine business recovery needs before purchasing a site or deploying recovery technology. Do not treat BIA as the first action in every possible continuity-planning workflow.','ในโจทย์นี้ต้องกำหนดความต้องการกู้คืนทางธุรกิจก่อนซื้อบริการสถานที่สำรองหรือติดตั้งเทคโนโลยี อย่าเหมารวมว่า BIA เป็นขั้นตอนแรกของกระบวนการวางแผนความต่อเนื่องทุกกรณี')

mark(618,'Co-location/frequent-backup claims need the stated common-hazard context, not a universal compliance or uselessness claim.',['R10','L06'])
correct(618,'In the stated flood scenario, production and co-located backups share a physical failure domain. Backup frequency alone does not protect recovery data from an event that can damage both copies; the recovery strategy must address that common hazard.','ในสถานการณ์น้ำท่วมตามโจทย์ ระบบหลักและข้อมูลสำรองที่อยู่ร่วมสถานที่มีจุดเสี่ยงต่อเหตุทางกายภาพร่วมกัน ความถี่ในการสำรองเพียงอย่างเดียวไม่ได้ป้องกันข้อมูลสำหรับกู้คืนจากเหตุที่อาจทำลายทั้งสองชุด แผนกู้คืนจึงต้องจัดการภัยร่วมดังกล่าว')
tip(618,'Assess common hazards affecting production and backups, and verify that the recovery copies remain accessible and usable under the planned disaster conditions.','ประเมินภัยร่วมที่อาจกระทบทั้งระบบหลักและข้อมูลสำรอง และตรวจว่าชุดข้อมูลกู้คืนยังเข้าถึงและใช้งานได้ภายใต้เงื่อนไขภัยพิบัติที่วางแผนไว้')

mark(625,'MFA is presented as a guarantee against credential-stuffing takeover instead of reducing reliance on a leaked password.',['R02','L01'])
correct(625,'MFA requires an additional distinct factor, so the stolen username/password pair alone is insufficient when MFA is correctly enforced. It reduces credential-stuffing exposure but is not a guarantee against every takeover; factor strength and resistance to phishing or approval abuse matter.','MFA ต้องใช้ปัจจัยต่างประเภทเพิ่มเติม ทำให้คู่ชื่อผู้ใช้และรหัสผ่านที่ถูกขโมยเพียงอย่างเดียวไม่เพียงพอเมื่อบังคับใช้ MFA อย่างถูกต้อง วิธีนี้ลดความเสี่ยงจาก Credential stuffing แต่ไม่ได้รับประกันว่าจะป้องกันการยึดบัญชีได้ทุกกรณี ความแข็งแรงของปัจจัยและความต้านทานต่อ Phishing หรือการหลอกให้อนุมัติยังมีความสำคัญ')

mark(626,'Reporting is claimed to ensure containment/evidence preservation; rationale invents organizational policy; tip attributes a universal rule to ISC2.',['R12','L07'])
correct(626,'Following the stated recognize-and-report duty, the employee should promptly contact the designated response team or helpdesk using established procedures. Reporting enables authorized responders to assess containment and evidence needs; it does not by itself guarantee either outcome.','ตามหน้าที่ Recognize and report ที่ระบุในโจทย์ พนักงานควรติดต่อทีมตอบสนองหรือ Helpdesk ที่กำหนดโดยเร็วตามขั้นตอนองค์กร การรายงานช่วยให้ผู้ตอบสนองที่มีอำนาจประเมินการจำกัดผลกระทบและการเก็บหลักฐาน แต่ไม่ได้รับประกันผลลัพธ์ทั้งสองโดยตัวมันเอง')
wrong(626,'A','Negotiating with the sender is not the stated reporting duty and can expose the employee to further manipulation. Ransom decisions belong to the organization’s authorized process.','การต่อรองกับผู้ส่งไม่ใช่หน้าที่รายงานที่ระบุ และอาจเปิดทางให้พนักงานถูกหลอกเพิ่มเติม การตัดสินใจเรื่องค่าไถ่ต้องเป็นไปตามกระบวนการของผู้มีอำนาจในองค์กร')
wrong(626,'B','Installing an unapproved removal tool can alter evidence or introduce further risk. The employee should follow the reporting procedure rather than attempt an unauthorized cleanup.','การติดตั้งเครื่องมือลบมัลแวร์ที่ไม่ได้รับอนุมัติอาจเปลี่ยนแปลงหลักฐานหรือเพิ่มความเสี่ยง พนักงานควรทำตามขั้นตอนรายงานแทนการพยายามกำจัดมัลแวร์โดยไม่มีอำนาจ')
wrong(626,'C','Abrupt power removal can lose volatile evidence. In this recognize-and-report scenario it is not the prescribed first action; shutdown or isolation decisions should follow the response procedure and any urgent safety needs.','การตัดไฟทันทีอาจทำให้หลักฐานในหน่วยความจำชั่วคราวสูญหาย ในโจทย์ที่กำหนดหน้าที่ Recognize and report จึงไม่ใช่การกระทำแรกตามขั้นตอน การปิดเครื่องหรือแยกเครือข่ายต้องเป็นไปตามกระบวนการตอบสนองและความจำเป็นเร่งด่วนด้านความปลอดภัย')
tip(626,'Read the employee’s stated role and reporting procedure. Authorized containment and evidence handling depend on the incident and safety context.','อ่านบทบาทพนักงานและขั้นตอนรายงานที่โจทย์กำหนด การจำกัดผลกระทบและจัดการหลักฐานโดยผู้มีอำนาจขึ้นกับบริบทเหตุการณ์และความปลอดภัย')

mark(627,'Unsupported legal entitlement and NIST violation claims; counts are dismissed categorically rather than contextualized.',['R11','L06'])
correct(627,'The count alone does not show whether important assets are protected or business risk is improving. In this board briefing it needs context such as scope, trends, exposure and control objectives; counts can still be useful when linked to a defined decision.','จำนวนครั้งเพียงอย่างเดียวไม่ได้แสดงว่าทรัพย์สินสำคัญได้รับการปกป้องหรือความเสี่ยงทางธุรกิจดีขึ้น ในรายงานต่อคณะกรรมการนี้ต้องมีบริบท เช่น ขอบเขต แนวโน้ม ความเสี่ยง และวัตถุประสงค์ของมาตรการ จำนวนครั้งยังมีประโยชน์ได้เมื่อเชื่อมโยงกับการตัดสินใจที่กำหนดไว้')
wrong(627,'B','The scenario supplies no legal rule forbidding this disclosure to the board. The stated problem is lack of decision-relevant context, not a blanket prohibition on board access to firewall statistics.','โจทย์ไม่ได้ระบุกฎหมายที่ห้ามเปิดเผยสถิตินี้ต่อคณะกรรมการ ปัญหาคือขาดบริบทที่ช่วยตัดสินใจ ไม่ใช่ข้อห้ามทั่วไปไม่ให้คณะกรรมการเข้าถึงสถิติไฟร์วอลล์')
wrong(627,'D','Multiplying by processor count has no defined relationship to the stated control-effectiveness or risk objective. Such a calculation needs a justified measurement model, not an invented formula.','การคูณจำนวนหน่วยประมวลผลไม่ได้มีความสัมพันธ์ที่กำหนดไว้กับเป้าหมายประสิทธิผลของมาตรการหรือความเสี่ยงตามโจทย์ การคำนวณต้องมีแบบจำลองการวัดที่อธิบายได้ ไม่ใช่สูตรที่สมมติขึ้น')
example(627,'A board report can relate blocked traffic trends to the monitored scope, exposed critical services and identified control gaps, explaining the limits of what the counts demonstrate.','รายงานต่อคณะกรรมการอาจเชื่อมแนวโน้มทราฟฟิกที่ถูกบล็อกกับขอบเขตที่เฝ้าระวัง บริการสำคัญที่เปิดรับการเชื่อมต่อ และช่องว่างของมาตรการ พร้อมอธิบายข้อจำกัดของสิ่งที่ตัวเลขแสดงได้')
tip(627,'Choose measures that support the intended audience’s decision. Counts, rates, percentages and trends all require defined scope and interpretation.','เลือกตัวชี้วัดที่สนับสนุนการตัดสินใจของกลุ่มเป้าหมาย จำนวนครั้ง อัตรา ร้อยละ และแนวโน้มล้วนต้องกำหนดขอบเขตและวิธีตีความ')

mark(628,'One incident is conflated with MTTD; alert-to-containment is labeled a universal respond metric.',['R11','L06'])
correct(628,'For this incident, using the supplied 10:00 detection milestone, TTD is 10:00 minus 08:00, or 2 hours. A mean time to detect would require averaging defined detection intervals over a set of incidents.','สำหรับเหตุการณ์นี้ เมื่อใช้จุดตรวจพบเวลา 10:00 ตามข้อมูลในโจทย์ TTD คือ 10:00 ลบ 08:00 เท่ากับ 2 ชั่วโมง ส่วน Mean time to detect ต้องคำนวณค่าเฉลี่ยของช่วงเวลาตรวจพบที่กำหนดไว้จากหลายเหตุการณ์')
wrong(628,'D','The 1.5-hour interval runs from the detection alert to host isolation. It is a detection-to-containment interval, not the compromise-to-detection interval asked for; a response metric needs its own defined endpoints.','ช่วง 1.5 ชั่วโมงนับจากการแจ้งเตือนตรวจพบถึงการแยกเครื่อง เป็นช่วงเวลาจากตรวจพบถึงจำกัดผลกระทบ ไม่ใช่จากเริ่มถูกเจาะถึงตรวจพบที่โจทย์ถาม และตัวชี้วัดการตอบสนองต้องกำหนดจุดเริ่มและจุดสิ้นสุดของตนเอง')
tip(628,'Use the stated milestones and units. TTD describes this incident; MTTD is an average over an explicitly defined incident set.','ใช้จุดเวลาและหน่วยที่โจทย์ระบุ TTD อธิบายเหตุการณ์นี้ ส่วน MTTD เป็นค่าเฉลี่ยของกลุ่มเหตุการณ์ที่กำหนดไว้อย่างชัดเจน')

mark(633,'Tip asserts an exclusive universal board/report audience rule rather than the stated communication requirement.',['R11','L06'])
tip(633,'Match the information, level of detail and format to the decision and audience. A strategic report fits this scenario; boards can also use suitable scorecards or dashboards.','จับคู่ข้อมูล ระดับรายละเอียด และรูปแบบกับการตัดสินใจและกลุ่มเป้าหมาย รายงานเชิงกลยุทธ์เหมาะกับโจทย์นี้ แต่คณะกรรมการอาจใช้ Scorecard หรือ Dashboard ที่เหมาะสมได้เช่นกัน')

mark(636,'Risk-acceptance authority is assigned universally by job title instead of governance delegation.',['R06','L06'])
correct(636,'The residual risk should be documented and referred to the designated risk-acceptance authority. Among these options, the designated business asset owner best matches that governance responsibility; the organization must define the owner’s authority and escalation limits.','ควรบันทึกความเสี่ยงที่เหลือและเสนอให้ผู้มีอำนาจยอมรับความเสี่ยงที่ได้รับมอบหมาย ในบรรดาตัวเลือก เจ้าของทรัพย์สินทางธุรกิจที่ได้รับมอบหมายตรงกับความรับผิดชอบด้านการกำกับดูแลมากที่สุด โดยองค์กรต้องกำหนดอำนาจและขอบเขตการส่งต่อของเจ้าของนั้น')
wrong(636,'B','Deploying firewall rules does not itself authorize an administrator to accept the organization’s business risk. The scenario identifies no such delegation to the junior administrator.','การติดตั้งกฎไฟร์วอลล์ไม่ได้ให้อำนาจผู้ดูแลระบบยอมรับความเสี่ยงทางธุรกิจขององค์กรโดยตัวมันเอง และโจทย์ไม่ได้ระบุการมอบอำนาจดังกล่าวแก่ผู้ดูแลระบบระดับต้น')
tip(636,'Check that residual risk is documented and accepted through the organization’s designated authority. Technical implementation alone is not risk-acceptance authorization.','ตรวจว่าความเสี่ยงที่เหลือได้รับการบันทึกและยอมรับผ่านผู้มีอำนาจที่องค์กรกำหนด การนำมาตรการทางเทคนิคไปใช้เพียงอย่างเดียวไม่ใช่การมอบอำนาจยอมรับความเสี่ยง')

mark(638,'Discussion-based exercise is generalized as a mandatory universal progression with zero operational effect.',['R10','L07'])
correct(638,'A discussion-based tabletop exercise fits the stated goal of reviewing roles, recovery procedures and communications without intentionally interrupting production. It can expose procedural gaps, but does not demonstrate that technical recovery or failover will work.','การฝึกซ้อม Tabletop แบบอภิปรายเหมาะกับเป้าหมายทบทวนบทบาท ขั้นตอนกู้คืน และการสื่อสาร โดยไม่จงใจหยุดระบบจริง สามารถช่วยพบช่องว่างของกระบวนการ แต่ไม่ได้พิสูจน์ว่าการกู้คืนทางเทคนิคหรือ Failover จะทำงานได้')
wrong(638,'C','The proposed 48-hour parallel processing test requires recovery resources and operational coordination beyond the low-cost discussion sought here. Exercise selection depends on objectives and risk, not a universal sequence.','การทดสอบประมวลผลคู่ขนาน 48 ชั่วโมงที่เสนอต้องใช้ทรัพยากรกู้คืนและการประสานงานเกินกว่าการอภิปรายต้นทุนต่ำที่ต้องการในโจทย์ การเลือกแบบฝึกขึ้นกับวัตถุประสงค์และความเสี่ยง ไม่ใช่ลำดับเดียวที่ใช้ทุกกรณี')
tip(638,'Choose the exercise that tests the stated objective within the disruption and resource constraints. Discussion and technical execution provide different evidence; terminology and progression may vary by program.','เลือกการฝึกที่ตรวจสอบวัตถุประสงค์ตามข้อจำกัดเรื่องผลกระทบและทรัพยากร การอภิปรายและการลงมือทดสอบทางเทคนิคให้หลักฐานต่างกัน และชื่อหรือขั้นตอนการฝึกอาจแตกต่างตามโปรแกรม')

mark(639,'Shortest MTD is asserted as a universal recovery sequence ignoring dependencies.',['R10','L06'])
correct(639,'Among the listed choices, emergency dispatch has the stated safety-critical function and the shortest downtime tolerance, so it is the best recovery priority on the supplied facts. An actual recovery sequence must also account for the BIA’s dependencies, prerequisites and approved recovery objectives.','ในบรรดาตัวเลือก ระบบ Emergency dispatch มีหน้าที่สำคัญต่อความปลอดภัยตามโจทย์และมีระยะเวลาที่ทนต่อการหยุดทำงานสั้นที่สุด จึงควรได้รับความสำคัญในการกู้คืนจากข้อมูลที่ให้มา ส่วนลำดับกู้คืนจริงต้องพิจารณาระบบที่พึ่งพากัน เงื่อนไขก่อนดำเนินการ และเป้าหมายกู้คืนที่อนุมัติใน BIA ด้วย')

mark(645,'Tip attributes a fixed audience-format rule to the CC exam.',['R11','L06'])
tip(645,'In this scenario, a live dashboard fits SOC monitoring and a periodic scorecard fits target-based review. Select formats by the audience’s actual decisions, not by an exclusive job-title rule.','ในโจทย์นี้ Dashboard แบบสดเหมาะกับการเฝ้าระวังของ SOC และ Scorecard เป็นระยะเหมาะกับการทบทวนตามเป้าหมาย เลือกรูปแบบตามการตัดสินใจจริงของกลุ่มเป้าหมาย ไม่ใช่กฎที่ผูกตายตัวกับชื่อตำแหน่ง')

mark(1018,'Thai stem omits the English MOST appropriate qualifier.',['R01','L08'])
work[1018]['question_th']=work[1018]['question_th'].replace('ควรใช้รายงานอย่างไร?','การใช้รายงานในข้อใดเหมาะสมที่สุด?')


# Short forms must not retain the academic overclaims corrected in detailed feedback.
for i,text in {
592:'Qualitative analysis uses descriptive categories and expert judgment; quantitative analysis requires meaningful numerical estimates.',
612:'Risk decisions require designated authority and knowledge of the affected business process; authority is assigned by governance.',
614:'Ordinal risk scales support semi-quantitative ranking; arithmetic alone does not establish quantitative measurement.',
616:'Here, a BIA establishes business recovery needs before recovery resources are selected.',
618:'Co-located production and backup copies may share the same disaster exposure; backup frequency alone does not address that hazard.',
625:'Correctly enforced MFA makes stolen passwords alone insufficient and reduces credential-stuffing risk.',
627:'A raw firewall count needs business and control context to support the board’s decision.',
633:'A business-aligned executive report fits the strategic decision needs stated in this scenario.',
636:'Residual risk should be documented and accepted through the designated organizational authority.',
638:'A tabletop can review roles and procedures without intentionally interrupting production; it does not prove technical recovery.',
639:'Recovery priorities consider business criticality, downtime tolerances and system dependencies.'
}.items():work[i]['short_explanation_en']=text
example(612,'If a hospital designates its Pharmacy Director as the risk owner, that person evaluates pharmacy impacts and makes or escalates the decision within the assigned authority.','หากโรงพยาบาลมอบหมายให้หัวหน้าฝ่ายเภสัชกรรมเป็นเจ้าของความเสี่ยง บุคคลนั้นจะประเมินผลกระทบต่องานเภสัชกรรมและตัดสินใจหรือส่งต่อภายในขอบเขตอำนาจที่ได้รับ')
tip(614,'Distinguish descriptive categories, ordinal ranking scales and numerical estimates with meaningful units. Financial estimates are examples of quantitative analysis, not its only form.','แยกระดับเชิงพรรณนา มาตราส่วนจัดอันดับ และค่าประมาณตัวเลขที่มีหน่วยมีความหมาย การประมาณทางการเงินเป็นตัวอย่างการวิเคราะห์เชิงปริมาณ ไม่ใช่รูปแบบเดียว')
example(616,'A BIA identifies the impact of losing emergency telemetry and cafeteria inventory, including dependencies needed to recover each function. That evidence informs recovery priorities.','BIA ระบุผลกระทบจากการสูญเสียระบบติดตามสัญญาณชีพฉุกเฉินและระบบสต็อกโรงอาหาร รวมถึงระบบที่แต่ละหน้าที่ต้องพึ่งพาในการกู้คืน หลักฐานนี้ใช้ประกอบการจัดลำดับความสำคัญ')
example(618,'A recovery plan considers whether flooding could affect both the production room and its backup storage, then provides protected recovery copies outside that common hazard where needed.','แผนกู้คืนพิจารณาว่าน้ำท่วมอาจกระทบทั้งห้องระบบหลักและที่เก็บข้อมูลสำรองหรือไม่ แล้วจัดให้มีชุดข้อมูลกู้คืนที่ได้รับการปกป้องอยู่นอกภัยร่วมดังกล่าวตามความจำเป็น')


# Remove two residual inconsistencies found while checking complete EN/TH variants.
work[588]['explanation']=work[588]['explanation'].replace('constitutes two-step or multi-credential authentication, but not multi-factor authentication','still constitutes single-factor authentication, not multi-factor authentication')
work[588]['explanation_th']=work[588]['explanation_th'].replace('จึงเป็นเพียง Two-step authentication ไม่ใช่ MFA','จึงยังคงเป็นการพิสูจน์ตัวตนแบบปัจจัยเดียว ไม่ใช่ MFA')
work[591]['explanation_th']=work[591]['explanation_th'].replace('ซอฟต์แวร์ที่ยังไม่ลงแพตช์จึงเป็นตัวอย่าง','ข้อบกพร่องในซอฟต์แวร์ที่ยังไม่ได้แพตช์จึงเป็นตัวอย่าง')
example(625,'An employee reuses the same long password on a personal service and corporate email. With the distinct additional factor enforced, replaying that password alone is rejected; this does not establish protection against an attacker who also defeats that factor.','พนักงานใช้รหัสผ่านยาวเดียวกันกับบริการส่วนตัวและอีเมลองค์กร เมื่อบังคับใช้ปัจจัยต่างประเภทเพิ่มเติม การนำรหัสผ่านนั้นมาใช้ซ้ำเพียงอย่างเดียวจะถูกปฏิเสธ แต่ไม่ได้แสดงว่าป้องกันผู้โจมตีที่เอาชนะปัจจัยเพิ่มเติมได้ด้วย')
example(626,'The employee uses the established helpdesk contact to report the ransom message. Authorized responders then assess containment and evidence handling under the incident procedure.','พนักงานใช้ช่องทาง Helpdesk ที่กำหนดเพื่อรายงานข้อความเรียกค่าไถ่ จากนั้นผู้ตอบสนองที่มีอำนาจจะประเมินการจำกัดผลกระทบและจัดการหลักฐานตามขั้นตอนเหตุการณ์')

# Whenever the core academic rationale changes, keep both flat versions aligned.
for i in [592,595,600,612,613,614,616,618,625,626,627,628,636,638,639]:flats(i)
proposals=[]
for i,meta in issues.items():
 changes={k:{'before':original[i][k],'after':work[i][k]} for k in original[i] if work[i][k]!=original[i][k]}
 assert changes and not {'id','dom','options','options_th','correct_idx'}&set(changes)
 proposals.append({'id':i,'domain':original[i]['dom'],**meta,'safe_to_apply':True,'key_before':'ABCD'[original[i]['correct_idx']],'key_proposed':'unchanged','fields':changes})
(OUT/'change-proposals.json').write_text(json.dumps(proposals,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Prepared',len(proposals),'record proposals:',[p['id'] for p in proposals],'; bank not edited.')
